import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PORT = process.env.PORT ? Number(process.env.PORT) : 8080;
const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'workboard.db');

// Initialize DB
const db = new DatabaseSync(DB_PATH);
db.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  );
`);

// Helper to parse JSON body
function parseJsonBody(req) {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', chunk => { data += chunk; });
    req.on('end', () => {
      try {
        resolve(JSON.parse(data || '{}'));
      } catch (e) {
        reject(e);
      }
    });
    req.on('error', err => reject(err));
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const pathname = url.pathname;

  // Health endpoint
  if (pathname === '/health' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }

  // API routes
  if (pathname === '/api/projects' && req.method === 'GET') {
    const rows = db.prepare('SELECT id, name FROM projects ORDER BY id ASC').all();
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(rows));
    return;
  }

  if (pathname === '/api/projects' && req.method === 'POST') {
    try {
      const body = await parseJsonBody(req);
      const name = (body.name || '').trim();
      if (!name) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Project name is required' }));
        return;
      }
      const stmt = db.prepare('INSERT INTO projects (name) VALUES (?)');
      const info = stmt.run(name);
      const newProject = { id: info.lastInsertRowid, name };
      res.writeHead(201, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(newProject));
    } catch (e) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Internal server error' }));
    }
    return;
  }

  if (pathname.startsWith('/api/projects/') && req.method === 'GET') {
    const id = pathname.split('/').pop();
    const row = db.prepare('SELECT id, name FROM projects WHERE id = ?').get(id);
    if (!row) {
      res.writeHead(404, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Not found' }));
    } else {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(row));
    }
    return;
  }

  // Serve static assets from public directory
  // For any GET request, try to serve file, fallback to index.html for SPA routes
  if (req.method === 'GET') {
    let filePath = path.join(__dirname, 'public', pathname);
    try {
      const stat = await (await import('node:fs')).promises.stat(filePath);
      if (stat.isDirectory()) {
        filePath = path.join(filePath, 'index.html');
      }
      const data = await readFile(filePath);
      const ext = path.extname(filePath).toLowerCase();
      const mime = {
        '.html': 'text/html',
        '.js': 'application/javascript',
        '.css': 'text/css',
        '.json': 'application/json',
        '.png': 'image/png',
        '.jpg': 'image/jpeg',
        '.gif': 'image/gif',
        '.svg': 'image/svg+xml',
      }[ext] || 'application/octet-stream';
      res.writeHead(200, { 'Content-Type': mime });
      res.end(data);
    } catch (_) {
      // fallback to index.html for client-side routing
      try {
        const indexPath = path.join(__dirname, 'public', 'index.html');
        const data = await readFile(indexPath);
        res.writeHead(200, { 'Content-Type': 'text/html' });
        res.end(data);
      } catch (e) {
        res.writeHead(404, { 'Content-Type': 'text/plain' });
        res.end('Not found');
      }
    }
    return;
  }

  // Method not allowed
  res.writeHead(405, { 'Content-Type': 'text/plain' });
  res.end('Method Not Allowed');
});

server.listen(PORT, '0.0.0.0', () => {
  console.log(`Server listening on http://0.0.0.0:${PORT}`);
});

// Client-side code for Workboard application

const API_BASE = '/api';

function $(sel) {
  return document.querySelector(sel);
}

function createEl(tag, attrs = {}, ...children) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k === 'class') el.className = v;
    else if (k.startsWith('data-')) el.setAttribute(k, v);
    else el[k] = v;
  }
  for (const child of children) {
    if (typeof child === 'string') el.appendChild(document.createTextNode(child));
    else if (child) el.appendChild(child);
  }
  return el;
}

async function fetchJson(url, opts = {}) {
  const resp = await fetch(url, { headers: { 'Content-Type': 'application/json' }, ...opts });
  const data = await resp.json().catch(() => ({}));
  if (!resp.ok) throw data;
  return data;
}

function showAlert(msg) {
  // Simple visible alert using window.alert (acceptable for visibility)
  alert(msg);
}

async function renderProjectList() {
  const list = $('#project-list');
  list.innerHTML = '';
  const projects = await fetchJson(`${API_BASE}/projects`);
  for (const p of projects) {
    const row = createEl('div', { 'data-testid': 'project-row', class: 'project-row' },
      createEl('span', {}, p.name),
      createEl('button', { class: 'open-btn' }, 'Open project')
    );
    row.querySelector('.open-btn').addEventListener('click', () => {
      window.location.href = `/projects/${p.id}`;
    });
    list.appendChild(row);
  }
}

async function loadProjectsPage() {
  const app = $('#app');
  app.innerHTML = '';
  const heading = createEl('h1', {}, 'Workboard');
  const form = createEl('div', {},
    createEl('label', { for: 'project-name' }, 'Project name'),
    createEl('input', { type: 'text', id: 'project-name' }),
    createEl('button', { id: 'create-btn' }, 'Create project')
  );
  const listContainer = createEl('div', { id: 'project-list' });
  app.append(heading, form, listContainer);

  $('#create-btn').addEventListener('click', async () => {
    const nameInput = $('#project-name');
    const name = nameInput.value.trim();
    try {
      await fetchJson(`${API_BASE}/projects`, {
        method: 'POST',
        body: JSON.stringify({ name })
      });
      nameInput.value = '';
      await renderProjectList();
    } catch (e) {
      if (e.error) showAlert(e.error);
      else showAlert('Failed to create project');
    }
  });

  await renderProjectList();
}

async function loadProjectDetailPage(id) {
  const app = $('#app');
  app.innerHTML = '';
  const proj = await fetchJson(`${API_BASE}/projects/${id}`);
  const heading = createEl('h1', {}, proj.name);
  const backBtn = createEl('button', {}, 'Projects');
  backBtn.addEventListener('click', () => {
    window.location.href = '/';
  });
  app.append(heading, backBtn);
}

function router() {
  const path = window.location.pathname;
  if (path === '/' || path === '/index.html') {
    loadProjectsPage();
  } else if (path.startsWith('/projects/')) {
    const id = path.split('/').pop();
    loadProjectDetailPage(id);
  } else {
    loadProjectsPage();
  }
}

window.addEventListener('load', router);
window.addEventListener('popstate', router);

